"""Language descriptions and name lookup for the counter."""
import json
from pathlib import Path
import pkgutil


def resource(name):
    try:
        return (Path(__file__).parent / name).read_text(encoding='utf-8')
    except (NotADirectoryError, FileNotFoundError):
        import zipfile
        with zipfile.ZipFile(Path(__file__).parent) as archive:
            return archive.read(name).decode('utf-8')


LANGUAGES = json.loads(resource('languages.json'))
ORDER = {name: i for i, name in enumerate(LANGUAGES)}
NAMES = {name.lower(): name for name in LANGUAGES}
EXTENSIONS = {}
for name, spec in LANGUAGES.items():
    for ext in spec['extensions']:
        EXTENSIONS.setdefault(ext.lower(), name)

FILE_NAMES = {
    'makefile': 'Makefile', 'gnumakefile': 'Makefile',
    'cmakelists.txt': 'CMake', 'dockerfile': 'Dockerfile',
    'justfile': 'Just', 'rakefile': 'Rakefile',
    'meson.build': 'Meson', 'meson_options.txt': 'Meson',
    'nuget.config': 'NuGet Config', 'pkgbuild': "Pacman's makepkg",
    'sconstruct': 'Scons', 'sconscript': 'Scons',
}

SHEBANGS = {
    '/bin/bash': 'BASH', '/usr/bin/env bash': 'BASH',
    '/bin/sh': 'Shell', '/usr/bin/env sh': 'Shell',
    '/bin/csh': 'C Shell', '/usr/bin/env csh': 'C Shell',
    '/bin/ksh': 'Korn shell', '/usr/bin/env ksh': 'Korn shell',
    '/usr/bin/env fish': 'Fish',
    '/usr/bin/env groovy': 'Groovy',
    '/usr/bin/env python': 'Python', '/usr/bin/env python2': 'Python',
    '/usr/bin/env python3': 'Python',
    '/usr/bin/perl': 'Perl',
    '/usr/bin/raku': 'Raku', '/usr/bin/env raku': 'Raku',
    '/usr/bin/env ruby': 'Ruby',
}


def language_name(text):
    return NAMES.get(text.lower())


def ordered(mapping):
    return {k: mapping[k] for k in sorted(mapping, key=lambda n: ORDER.get(n, 10000))}


def identify(path, contents=None):
    name = Path(path).name
    known = FILE_NAMES.get(name.lower())
    if known:
        return known
    # A leading dot, by itself, is not an extension separator.
    if '.' in name[1:]:
        return EXTENSIONS.get(name.rsplit('.', 1)[-1].lower())
    if contents is None:
        try:
            with open(path, 'rb') as f:
                contents = f.readline(4096)
        except OSError:
            return None
    if isinstance(contents, bytes):
        contents = contents.decode('utf-8', errors='replace')
    line = contents.split('\n', 1)[0].strip(' \t\r')
    if line.startswith('#!'):
        return SHEBANGS.get(line[2:].strip())
    return None
