"""Small, explicit statistics records; aggregation preserves embedded reports."""
from data import ordered

FIELDS = ('blanks', 'code', 'comments')


def stats():
    return {'blanks': 0, 'code': 0, 'comments': 0, 'blobs': {}}


def language():
    return {'blanks': 0, 'code': 0, 'comments': 0,
            'reports': [], 'children': {}, 'inaccurate': False}


def add(target, source):
    for k in FIELDS:
        target[k] += source[k]
    if 'blobs' in target:
        for name, child in source.get('blobs', {}).items():
            add(target['blobs'].setdefault(name, stats()), child)
        target['blobs'] = ordered(target['blobs'])
    return target


def total_of(s):
    t = stats()
    for k in FIELDS:
        t[k] = s[k]
    for blob in s.get('blobs', {}).values():
        add(t, total_of(blob))
    return t


def lines(s):
    return s['blanks'] + s['code'] + s['comments']


def aggregate(records):
    langs = {}
    for name, path, s in records:
        l = langs.setdefault(name, language())
        add(l, s)
        l['reports'].append({'stats': s, 'name': path})
        for child, cs in s['blobs'].items():
            l['children'].setdefault(child, []).append({'stats': cs, 'name': path})
    langs = ordered(langs)
    total = language()
    for name, l in langs.items():
        l['children'] = ordered(l['children'])
        total['children'][name] = l['reports']
        for report in l['reports']:
            add(total, total_of(report['stats']))
    return langs, total


def language_total(l):
    t = stats()
    for k in FIELDS:
        t[k] = l[k]
    for reports in l['children'].values():
        for r in reports:
            add(t, total_of(r['stats']))
    return t
