"""Line-oriented lexical counting with separate statistics for embedded languages."""
import json
import re
from data import LANGUAGES, language_name, ordered
from stats import stats, add, total_of

WS = ' \t\n\r\v\f'


def physical_lines(text):
    if not text:
        return []
    ls = text.split('\n')
    if ls[-1] == '':
        ls.pop()
    return ls


def decode_file(content):
    if content.startswith(b'\xff\xfe'):
        return content[2:].decode('utf-16-le', errors='replace')
    if content.startswith(b'\xfe\xff'):
        return content[2:].decode('utf-16-be', errors='replace')
    if content.startswith(b'\xef\xbb\xbf'):
        content = content[3:]
    return content.decode('utf-8', errors='replace')


def plain(text, comment=False):
    s = stats()
    for line in physical_lines(text):
        s['blanks' if not line.strip(WS) else 'comments' if comment else 'code'] += 1
    return s


def blob(s, name, value):
    add(s['blobs'].setdefault(name, stats()), value)
    s['blobs'] = ordered(s['blobs'])


def markdown(text, config, depth):
    s = stats()
    rest = text
    fence = re.compile(r'(?<!`)```(?!`)([^\s,`]+)')
    while rest:
        found = None
        for m in fence.finditer(rest):
            lang = language_name(m.group(1))
            if lang:
                found = (m, lang)
                break
        if not found:
            add(s, plain(rest, True))
            break
        m, lang = found
        line_start = rest.rfind('\n', 0, m.start()) + 1
        add(s, plain(rest[:line_start], True))
        s['comments'] += 1
        body_start = m.end()
        if body_start < len(rest) and rest[body_start] == ',':
            end = rest.find('\n', body_start)
            body_start = len(rest) if end < 0 else end
        close = rest.find('```', body_start)
        if close < 0:
            body = rest[body_start:].strip(WS)
            rest = ''
        else:
            body = rest[body_start:close].strip(WS)
            s['comments'] += 1
            rest = rest[close + 3:]
            if rest.startswith('\r\n'):
                rest = rest[2:]
            elif rest.startswith('\n'):
                rest = rest[1:]
        blob(s, lang, parse(lang, body, config, depth + 1))
    return s


def notebook(text, config, depth):
    out = stats()
    try:
        obj = json.loads(text)
        if not isinstance(obj, dict) or not isinstance(obj.get('cells'), list):
            return out
        if not all(k in obj for k in ('nbformat', 'nbformat_minor', 'metadata')):
            return out
        cells = obj['cells']
        for c in cells:
            if not isinstance(c, dict) or not all(k in c for k in ('cell_type', 'metadata', 'source')):
                return out
            if not isinstance(c['source'], list) or not all(isinstance(x, str) for x in c['source']):
                return out
        metadata = obj['metadata']
        name = (metadata.get('kernelspec') or {}).get('language') or (metadata.get('language_info') or {}).get('name') or 'Python'
        code_lang = language_name(name) or 'Python'
        for c in cells:
            if c['cell_type'] == 'code':
                lang = code_lang
            elif c['cell_type'] == 'markdown':
                lang = 'Markdown'
            else:
                continue
            child = parse(lang, ''.join(c['source']), config, depth + 1)
            blob(out, lang, child)
            for k in ('blanks', 'code', 'comments'):
                out[k] += child[k]
    except (ValueError, TypeError, AttributeError, KeyError):
        return stats()
    return out


def parse(lang, text, config=None, depth=0):
    config = config or {}
    if depth > 20:
        return plain(text)
    if lang == 'Jupyter Notebooks':
        return notebook(text, config, depth)
    if lang in ('Markdown', 'MDX'):
        return markdown(text, config, depth)
    spec = LANGUAGES.get(lang)
    if spec is None:
        return plain(text)
    if spec.get('text'):
        return plain(text, True)
    return lex(lang, text, spec, config, depth)


def lex(lang, text, spec, config, depth):
    s = stats()
    line_comments = sorted(spec['line'], key=len, reverse=True)
    blocks = sorted([tuple(x) for x in spec['block']], key=lambda x: -len(x[0]))
    nested = {tuple(x) for x in spec['nested']}
