"""File discovery with hierarchical ignore files and explicit path handling."""
import os
import re
from dataclasses import dataclass
from pathlib import Path


def glob_regex(pattern):
    out = ''
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            if pattern[i:i+2] == '**':
                i += 1
                if i + 1 < len(pattern) and pattern[i + 1] == '/':
                    out += '(?:.*/)?'
                    i += 1
                else:
                    out += '.*'
            else:
                out += '[^/]*'
        elif c == '?':
            out += '[^/]'
        elif c == '[':
            end = pattern.find(']', i + 1)
            if end >= 0:
                group = pattern[i+1:end]
                if group.startswith('!'):
                    group = '^' + group[1:]
                out += '[' + group + ']'
                i = end
            else:
                out += r'\['
        elif c == '\\' and i+1 < len(pattern):
            i += 1
            out += re.escape(pattern[i])
        else:
            out += re.escape(c)
        i += 1
    return re.compile('^' + out + '$')


@dataclass
class Rule:
    base: str
    expr: object
    basename: bool
    directory: bool
    negate: bool

    def match(self, path, isdir):
        if self.directory and not isdir:
            return False
        rel = os.path.relpath(path, self.base).replace(os.sep, '/')
        if rel == '..' or rel.startswith('../'):
            return False
        return bool(self.expr.match(os.path.basename(rel) if self.basename else rel))


def make_rule(text, base):
    text = text.rstrip('\r\n')
    text = re.sub(r'(?<!\\) +$', '', text)
    if not text or text.startswith('#'):
        return None
    negate = text.startswith('!')
    if negate:
        text = text[1:]
    directory = text.endswith('/')
    if directory:
        text = text[:-1]
    anchored = text.startswith('/')
    if anchored:
        text = text[1:]
    if not text:
        return None
    try:
        return Rule(os.path.abspath(base), glob_regex(text), not anchored and '/' not in text, directory, negate)
    except re.error:
        return None


def ignore_file(file, base):
    try:
        with open(file, encoding='utf-8', errors='replace') as f:
            return [r for line in f for r in [make_rule(line, base)] if r is not None]
    except OSError:
        return []


def ancestors(path):
    p = os.path.abspath(path)
    found = []
    while True:
        found.append(p)
        parent = os.path.dirname(p)
        if parent == p:
            return found[::-1]
        p = parent


def discover(paths, config):
    no_ignore = config.get('no_ignore', False)
    no_vcs = no_ignore or config.get('no_ignore_vcs', False)
    no_dot = no_ignore or config.get('no_ignore_dot', False)
    no_parent = no_ignore or config.get('no_ignore_parent', False)
    hidden = config.get('hidden', False)
    override = [r for pattern in config.get('exclude', []) for r in [make_rule(pattern, os.getcwd())] if r]

    def local_rules(directory, groups, repository):
        vcs, dot, custom = [list(x) for x in groups]
        if not no_vcs and repository:
            vcs.extend(ignore_file(os.path.join(directory, '.gitignore'), directory))
            if os.path.isdir(os.path.join(directory, '.git')):
                vcs.extend(ignore_file(os.path.join(directory, '.git', 'info', 'exclude'), directory))
        if not no_dot:
            dot.extend(ignore_file(os.path.join(directory, '.ignore'), directory))
            custom.extend(ignore_file(os.path.join(directory, '.tokeignore'), directory))
        return vcs, dot, custom

    def ignored(path, isdir, groups):
        result = None
        for rules in groups:
            for rule in rules:
                if rule.match(path, isdir):
                    result = not rule.negate
        for rule in override:
            # Bare excludes apply to arbitrary explicitly supplied roots as well.
            if rule.basename:
                match = (not rule.directory or isdir) and bool(rule.expr.match(os.path.basename(path)))
            else:
                match = rule.match(path, isdir)
            if match:
                result = not rule.negate
        return result

    def visit(directory, groups, repo):
        repo = repo or os.path.exists(os.path.join(directory, '.git'))
        groups = local_rules(directory, groups, repo)
        try:
            entries = sorted(os.scandir(directory), key=lambda x: x.name)
        except OSError:
            return
        for entry in entries:
            name = entry.name
            if entry.is_symlink():
                continue
            path = os.path.join(directory, name)
            try:
                isdir = entry.is_dir(follow_symlinks=False)
            except OSError:
                continue
            exclusion = ignored(path, isdir, groups)
            if exclusion is True:
                continue
            if name.startswith('.') and not hidden and exclusion is not False:
                continue
            if isdir:
                yield from visit(path, groups, repo)
            elif entry.is_file(follow_symlinks=False):
                yield path

    for path in paths:
        if os.path.isfile(path):
            yield path
            continue
        if not os.path.isdir(path):
            continue
        parents = ancestors(os.path.dirname(os.path.abspath(path)))
        repo = any(os.path.exists(os.path.join(p, '.git')) for p in parents) or os.path.exists(os.path.join(path, '.git'))
        groups = ([], [], [])
        if not no_parent:
            for p in parents:
                groups = local_rules(p, groups, repo)
        yield from visit(path, groups, repo)
