"""Read the small scalar/array configuration vocabulary without dependencies."""
import ast
import os
import re
from pathlib import Path
from data import language_name


def read_config_file(path):
    try:
        data = Path(path).read_text(encoding='utf-8')
    except OSError:
        return {}
    values = {}
    try:
        # Configurations are a flat TOML table. Unrecognized keys are ignored.
        for line in data.splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if line.startswith('['):
                break
            m = re.match(r'([A-Za-z_][\w-]*)\s*=\s*(.*?)\s*$', line)
            if not m:
                return {}
            key, val = m.groups()
            # Remove a trailing comment without stripping hashes inside strings.
            quote = None
            escape = False
            for i, c in enumerate(val):
                if escape:
                    escape = False
                    continue
                if c == '\\' and quote == '"':
                    escape = True
                elif c == quote:
                    quote = None
                elif c in ('"', "'") and quote is None:
                    quote = c
                elif c == '#' and quote is None:
                    val = val[:i].strip()
                    break
            if val in ('true', 'false'):
                value = val == 'true'
            else:
                value = ast.literal_eval(val)
            values[key.replace('-', '_')] = value
    except (ValueError, SyntaxError):
        return {}
    allowed = ('columns', 'sort', 'types', 'hidden', 'no_ignore', 'no_ignore_parent', 'no_ignore_dot', 'no_ignore_vcs', 'treat_doc_strings_as_comments')
    return {k: v for k, v in values.items() if k in allowed}


def load_config():
    locations = []
    home = os.path.expanduser('~')
    if home:
        locations.append(Path(home))
    config_home = Path(os.environ.get('XDG_CONFIG_HOME', str(Path(home) / '.config')))
    locations.append(config_home / 'tokei')
    locations.append(Path.cwd())
    result = {}
    for d in locations:
        for filename in ('tokei.toml', '.tokeirc'):
            result.update(read_config_file(d / filename))
    return result
