import datetime
import json
import os
import sys
from cli import arguments
from config import load_config
from data import identify, language_name, resource
from lexer import parse, decode_file
from render import table, STREAM_HEADER, stream_record
from stats import aggregate
from walker import discover


def input_failure(value):
    sys.stderr.write(f'''Error:
 Failed to parse input file: {value}

This version of tokei was compiled without serialization support for the following formats:

    cbor, json, yaml

You may want to install any comma separated combination of "cbor,json,yaml":

    cargo install tokei --features "cbor,json,yaml"

Or use the 'all' feature:

    cargo install tokei --features all


''')
    raise SystemExit(1)


def read_previous(value):
    try:
        if value == 'stdin':
            text = sys.stdin.read()
        elif os.path.isfile(value):
            with open(value, encoding='utf-8') as f:
                text = f.read()
        else:
            text = value
        obj = json.loads(text)
        t = obj['Total']
        for key in ('blanks', 'code', 'comments', 'reports', 'children', 'inaccurate'):
            if key not in t:
                input_failure(value)
    except (OSError, ValueError, TypeError, KeyError):
        input_failure(value)


def main():
    cfg, paths = arguments(sys.argv[1:], load_config())
    if cfg.get('languages'):
        sys.stdout.write(resource('language-list.txt'))
        return
    if cfg.get('input'):
        read_previous(cfg['input'])
    for path in paths:
        if not os.path.exists(path):
            sys.stderr.write(f"Error: '{path}' not found.\n")
            raise SystemExit(1)
    selected = None
    if cfg.get('types') is not None:
        selected = {language_name(x) for x in cfg['types'] if isinstance(x, str)}
    records = []
    mode = cfg.get('streaming')
    if mode == 'simple':
        sys.stdout.write(STREAM_HEADER)
    for path in discover(paths, cfg):
        lang = identify(path)
        if not lang:
            if cfg.get('verbose', 0) >= 1:
                name = os.path.basename(path)
                if '.' in name[1:]:
                    ext = name.rsplit('.', 1)[-1]
                    now = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
                    sys.stderr.write(f'[{now} WARN  tokei::language::language_type] Unknown extension: {ext}\n')
            continue
        if selected is not None and lang not in selected:
            continue
        try:
            with open(path, 'rb') as f:
                content = decode_file(f.read())
        except OSError:
            continue
        s = parse(lang, content, cfg)
        records.append((lang, path, s))
        if mode:
            sys.stdout.write(stream_record(lang, path, s, mode))
    if mode:
        return
    languages, total = aggregate(records)
    if cfg.get('output') == 'json':
        value = dict(languages)
        value['Total'] = total
        sys.stdout.write(json.dumps(value, ensure_ascii=False, separators=(',', ':')))
    else:
        sys.stdout.write(table(languages, total, cfg))


if __name__ == '__main__':
    try:
        main()
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except BrokenPipeError:
            pass
        raise SystemExit(0)
