        return f' {label(name, lw):<{lw}} {number(files):>8} ' + metrics(s)

    def file_row(name, s, truncate=True):
        if truncate:
            if len(name) > fw:
                name = '|' + name[-(fw-1):]
            return f' {name:<{fw}} ' + metrics(s)
        return f' {name:<{fw-2}}   ' + metrics(s)

    out = [heavy, f' {"Language":<{lw}} {"Files":>8} {"Lines":>12} {"Code":>12} {"Comments":>12} {"Blanks":>12}', heavy]

    def value(l):
        return len(l['reports']) if sort == 'files' else lines(l) if sort == 'lines' else l.get(sort, 0)

    pairs = list(languages.items())
    if sort:
        pairs.sort(key=lambda kv: value(kv[1]), reverse=not reverse)
    pairs = [(n, l) for n, l in pairs if lines(language_total(l)) != 0]
    if not compact:
        pairs = [p for p in pairs if not p[1]['children']] + [p for p in pairs if p[1]['children']]
    for index, (name, l) in enumerate(pairs):
        if index and (show_files or (l['children'] and not compact)):
            out.append(light)
        out.append(lang_row(name, len(l['reports']), l))
        if l['children'] and not compact:
            for child_name, reports in l['children'].items():
                c = stats()
                for report in reports:
                    add(c, total_of(report['stats']))
                out.append(lang_row('|- ' + child_name, len(reports), c))
            out.append(file_row('(Total)', language_total(l)))
        if show_files:
            out.append(light)
            reports = sorted(l['reports'], key=lambda r: r['name'])
            if sort and sort != 'files':
                reports.sort(key=lambda r: lines(r['stats']) if sort == 'lines' else r['stats'][sort], reverse=not reverse)
            for report in reports:
                path, s = report['name'], report['stats']
                if not s['blobs'] or compact:
                    out.append(file_row(path, s))
                else:
                    out.append(' ' + path)
                    out.append(file_row('|- ' + name, s))
                    for child_name, cs in s['blobs'].items():
                        out.append(file_row('|- ' + child_name, cs))
                    out.append(file_row(path, s, False))
    out.append(heavy)
    out.append(lang_row('Total', sum(len(l['reports']) for l in languages.values()), total))
    out.append(heavy)
    return '\n'.join(out) + '\n'
