"""Command-line interface and error messages."""
import difflib
import os
import re
import sys
from data import resource

OPTIONS = {
    'columns': ('c', 'columns'), 'exclude': ('e', 'exclude'),
    'files': ('f', None), 'input': ('i', 'file_input'),
    'hidden': (None, None), 'languages': ('l', None),
    'no-ignore': (None, None), 'no-ignore-parent': (None, None),
    'no-ignore-dot': (None, None), 'no-ignore-vcs': (None, None),
    'output': ('o', 'output'), 'streaming': (None, 'streaming'),
    'sort': ('s', 'sort'), 'rsort': ('r', 'rsort'),
    'types': ('t', 'types'), 'compact': ('C', None),
    'num-format': ('n', 'num_format_style'),
    'verbose': ('v', None), 'help': ('h', None), 'version': ('V', None),
}
SHORT = {v[0]: k for k, v in OPTIONS.items() if v[0]}
ENUMS = {
    'streaming': ['simple', 'json'],
    'sort': ['files', 'lines', 'blanks', 'code', 'comments'],
    'rsort': ['files', 'lines', 'blanks', 'code', 'comments'],
    'num-format': ['commas', 'dots', 'plain', 'underscores'],
}


def desc(name):
    val = OPTIONS[name][1]
    return '--' + name + (' <' + val + '>' if val else '')


def fail(message):
    sys.stderr.write('error: ' + message + "\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def unknown(arg, prog):
    possible = difflib.get_close_matches(arg, ['--' + k for k in OPTIONS], n=1, cutoff=0.74) if arg.startswith('--') else []
    if possible:
        name = possible[0][2:]
        tip = f"  tip: a similar argument exists: '{possible[0]}'\n\nUsage: {prog} {desc(name)} [input]..."
    else:
        tip = f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {prog} [OPTIONS] [input]..."
    fail(f"unexpected argument '{arg}' found\n\n" + tip)


def serialization_error(fmt):
    if fmt in ('cbor', 'yaml'):
        reason = f"This version of tokei was compiled without any '{fmt}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {fmt}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n"
    else:
        reason = '"' + fmt + '" is not a supported serialization format'
    fail(f"invalid value '{fmt}' for '--output <output>': {reason}")


def arguments(argv, config):
    prog = os.path.basename(sys.argv[0])
    # Running from source is useful for development but still has the public CLI name.
    if prog == '__main__.py' or prog == 'src':
        prog = 'executable'
    cfg = dict(config)
    cfg.update(files=False, compact=False, num_format='plain', verbose=0, exclude=[])
    paths = []
    seen = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        i += 1
        if arg == '--':
            paths.extend(argv[i:])
            break
        if not arg.startswith('-') or arg == '-':
            paths.append(arg)
            continue
        pending = []
        if arg.startswith('--'):
            k, sep, val = arg[2:].partition('=')
            if k not in OPTIONS:
                unknown('--' + k, prog)
            pending = [(k, val if sep else None)]
        else:
            j = 1
            while j < len(arg):
                char = arg[j]
                if char not in SHORT:
                    unknown('-' + char, prog)
                k = SHORT[char]
                if OPTIONS[k][1]:
                    v = arg[j + 1:]
                    if v.startswith('='):
                        v = v[1:]
                    pending.append((k, v if j + 1 < len(arg) else None))
                    break
                pending.append((k, None))
                j += 1
        for k, val in pending:
            needs_value = OPTIONS[k][1] is not None
            if k in seen and k not in ('exclude', 'types', 'verbose'):
                fail(f"the argument '{desc(k)}' cannot be used multiple times\n\nUsage: {prog} [OPTIONS] [input]...")
            seen.append(k)
            if not needs_value and val is not None:
                fail(f"unexpected value '{val}' for '--{k}' found; no more were expected\n\nUsage: {prog} --{k} [input]...")
            if needs_value and val is None:
                if i >= len(argv) or argv[i].startswith('-') and argv[i] != '-':
                    if i < len(argv) and re.match(r'-\d', argv[i]):
                        unknown(argv[i], prog)
                    possible = '\n  [possible values: ' + ', '.join(ENUMS[k]) + ']' if k in ENUMS else ''
                    fail(f"a value is required for '{desc(k)}' but none was supplied" + possible)
                val = argv[i]
                i += 1
            if k == 'help':
                sys.stdout.write(resource('help.txt').replace('Usage: executable', 'Usage: ' + prog))
                raise SystemExit(0)
            if k == 'version':
                print('tokei 14.0.0 compiled with serialization support: json')
                raise SystemExit(0)
            if k in ENUMS and val not in ENUMS[k]:
                hint = ''
                close = difflib.get_close_matches(val, ENUMS[k], n=1, cutoff=0.75)
                if close:
                    hint = f"\n\n  tip: a similar value exists: '{close[0]}'"
                fail(f"invalid value '{val}' for '{desc(k)}'\n  [possible values: {', '.join(ENUMS[k])}]" + hint)
            if k == 'output' and val != 'json':
                serialization_error(val)
            if k == 'columns':
                if not re.fullmatch(r'\+?\d+', val):
                    fail(f"invalid value '{val}' for '{desc(k)}': invalid digit found in string")
                if int(val) > 2**64 - 1:
                    fail(f"invalid value '{val}' for '{desc(k)}': number too large to fit in target type")
                val = int(val)
            if k == 'exclude':
                cfg['exclude'].append(val)
            elif k == 'types':
                if seen.count(k) == 1:
                    cfg['types'] = []
                cfg['types'].extend(val.split(','))
            elif k == 'verbose':
                cfg['verbose'] += 1
            else:
                cfg[k.replace('-', '_')] = val if needs_value else True
    for a, b in [('sort', 'rsort'), ('output', 'num-format')]:
        if a in seen and b in seen:
            first, second = (a, b) if seen.index(a) < seen.index(b) else (b, a)
            inp = '<input>...' if paths else '[input]...'
            fail(f"the argument '{desc(first)}' cannot be used with '{desc(second)}'\n\nUsage: {prog} {desc(first)} {inp}")
    if 'rsort' in cfg:
        cfg['sort'] = cfg['rsort']
        cfg['sort_reverse'] = True
    if cfg.get('sort') not in ENUMS['sort']:
        cfg.pop('sort', None)
    return cfg, paths or ['.']
