"""Read the flat, scalar/array configuration vocabulary without dependencies."""
import ast
import os
import re
from pathlib import Path
from data import language_name


def strip_comment(value):
    quote = None
    escape = False
    for i, c in enumerate(value):
        if escape:
            escape = False
            continue
        if c == '\\' and quote == '"':
            escape = True
        elif c == quote:
            quote = None
        elif c in ('"', "'") and quote is None:
            quote = c
        elif c == '#' and quote is None:
            return value[:i].strip()
    return value.strip()


def read_config_file(path):
    try:
        data = Path(path).read_text(encoding='utf-8')
    except (OSError, UnicodeError):
        return {}
    values = {}
    try:
        lines = iter(data.splitlines())
        for line in lines:
            line = strip_comment(line.strip())
            if not line:
                continue
            if line.startswith('['):
                break
            m = re.match(r'([A-Za-z_][\w-]*)\s*=\s*(.*?)\s*$', line)
            if not m:
                return {}
            key, val = m.groups()
            if val.startswith('['):
                while not val.rstrip().endswith(']'):
                    val += '\n' + strip_comment(next(lines))
            if val in ('true', 'false'):
                value = val == 'true'
            else:
                value = ast.literal_eval(val)
            values[key.replace('-', '_')] = value
    except (StopIteration, ValueError, SyntaxError):
        return {}
    bool_fields = ('hidden', 'no_ignore', 'no_ignore_parent', 'no_ignore_dot', 'no_ignore_vcs', 'treat_doc_strings_as_comments')
    for key in bool_fields:
        if key in values and type(values[key]) is not bool:
            return {}
    if 'columns' in values:
        if type(values['columns']) is not int or not 0 <= values['columns'] < 2**64:
            return {}
    if 'types' in values:
        if not isinstance(values['types'], list) or not all(isinstance(v, str) and language_name(v) for v in values['types']):
            return {}
    if 'sort' in values and values['sort'] not in ('files', 'lines', 'blanks', 'code', 'comments'):
        return {}
    allowed = ('columns', 'sort', 'types') + bool_fields
    return {k: v for k, v in values.items() if k in allowed}


def load_config():
    home = os.path.expanduser('~')
    config_home = Path(os.environ.get('XDG_CONFIG_HOME', str(Path(home) / '.config')))
    locations = [config_home, Path(home), Path.cwd()]
    result = {}
    for d in locations:
        for filename in ('.tokeirc', 'tokei.toml'):
            result.update(read_config_file(d / filename))
    return result
