"""Regression tests for observed counting, traversal and interface behavior."""
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'src'))
from lexer import parse
from stats import aggregate


class LexerTests(unittest.TestCase):
    def assert_counts(self, lang, source, blanks, code, comments, config=None):
        result = parse(lang, source, config)
        self.assertEqual((result['blanks'], result['code'], result['comments']), (blanks, code, comments))
        return result

    def test_comments_and_blank_lines(self):
        self.assert_counts('C', '// heading\n\nx(); // inline\n/* a\n\n*/ y;\n', 1, 1, 4)
        self.assert_counts('Python', '# heading\n\nx=1 # inline\n', 1, 1, 1)
        self.assert_counts('Plain Text', 'hello\n\nworld\n', 1, 0, 2)
        self.assert_counts('JSON', '// not a JSON comment\n\n', 1, 1, 0)

    def test_nested_comments(self):
        self.assert_counts('Rust', '/*a\n/*b\n*/\nx\n*/\n', 0, 0, 5)
        self.assert_counts('C', '/*a\n/*b\n*/\nx\n*/\n', 0, 2, 3)
        self.assert_counts('Haskell', '{-a\n{-b-}\n-}\nx\n', 0, 1, 3)

    def test_strings(self):
        self.assert_counts('Python', 'x="""doc\n\ntext\n"""\n', 0, 4, 0)
        self.assert_counts('Python', 'x="""doc\n\ntext\n"""\n', 0, 0, 4, {'treat_doc_strings_as_comments': True})
        self.assert_counts('Rust', 'let x=r#"a " b\n// text\n\n"#;\n', 0, 4, 0)
        self.assert_counts('C', 'foo=\'"\';\n// text\n', 0, 2, 0)
        self.assert_counts('C', '"a\n// text"\n', 0, 1, 1)

    def test_markdown_and_rust_documentation(self):
        s = self.assert_counts('Markdown', '# Title\n\n```python\n\n#hi\nx\n\n```\n', 1, 0, 3)
        self.assertEqual(s['blobs']['Python'], {'blanks': 0, 'code': 1, 'comments': 1, 'blobs': {}})
        s = self.assert_counts('Rust', '/// text\n/// ```rust\n/// fn x(){}\n/// ```\n\nfn main(){}\n', 1, 1, 0)
        self.assertEqual(s['blobs']['Markdown']['comments'], 3)
        self.assertEqual(s['blobs']['Markdown']['blobs']['Rust']['code'], 1)
        self.assert_counts('MDX', '```python\nx\n```\n', 0, 0, 3)

    def test_embedded_html(self):
        s = self.assert_counts('HTML', '<script>\n// hi\nx\n\n</script>\n', 0, 2, 0)
        self.assertEqual(s['blobs']['JavaScript'], {'blanks': 1, 'code': 1, 'comments': 1, 'blobs': {}})
        s = self.assert_counts('HTML', '<script>// inline</script>\n', 0, 2, 0)
        self.assertEqual(s['blobs']['JavaScript']['code'], 1)
        self.assert_counts('HTML', '<script>\n\n</script>\n', 1, 2, 0)

    def test_notebook(self):
        n = {'metadata': {'kernelspec': {'language': 'python'}, 'language_info': {}},
             'cells': [{'cell_type': 'code', 'source': ['# hi\n', 'x\n']}]}
        s = self.assert_counts('Jupyter Notebooks', json.dumps(n), 0, 1, 1)
        self.assertIn('Python', s['blobs'])
        self.assert_counts('Jupyter Notebooks', '{}', 0, 0, 0)


class CLITests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def run_tool(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(ROOT / 'src'), *args], cwd=self.root,
                              input=stdin, text=True, capture_output=True)

    def write(self, name, source):
        p = self.root / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(source)

    def test_empty_output(self):
        p = self.run_tool('-o', 'json')
        self.assertEqual(p.returncode, 0)
        self.assertEqual(p.stdout, '{"Total":{"blanks":0,"code":0,"comments":0,"reports":[],"children":{},"inaccurate":false}}')
        p = self.run_tool()
        self.assertTrue(p.stdout.endswith('━' * 81 + '\n'))
        self.assertIn(' Total                     0', p.stdout)

    def test_discovery_ignores(self):
        self.write('a.py', '# hi\nx\n')
        self.write('.hidden.py', 'x\n')
        self.write('sub/skip.py', 'x\n')
        self.write('.ignore', 'sub/\n')
        value = json.loads(self.run_tool('-o', 'json').stdout)
        self.assertEqual(len(value['Python']['reports']), 1)
        value = json.loads(self.run_tool('--no-ignore', '--hidden', '-o', 'json').stdout)
        self.assertEqual(len(value['Python']['reports']), 3)
        value = json.loads(self.run_tool('-o', 'json', 'sub').stdout)
        self.assertEqual(value['Python']['reports'][0]['name'], 'sub/skip.py')

    def test_gitignore_requires_repository(self):
        self.write('a.py', 'x\n')
        self.write('.gitignore', '*.py\n')
        self.assertIn('Python', json.loads(self.run_tool('-o', 'json').stdout))
        (self.root / '.git').mkdir()
        self.assertNotIn('Python', json.loads(self.run_tool('-o', 'json').stdout))

    def test_files_types_and_columns(self):
        self.write('a.py', 'x\n')
        self.write('a.rs', '// comment\nx\n')
        p = self.run_tool('-f', '-c', '100', '-t', 'Python')
        self.assertEqual(len(p.stdout.splitlines()[0]), 100)
        self.assertIn('./a.py', p.stdout)
        self.assertNotIn('Rust', p.stdout)

    def test_streaming(self):
        self.write('a.py', '# hi\nx\n')
        p = self.run_tool('--streaming', 'json', 'a.py')
        self.assertEqual(json.loads(p.stdout)['stats']['stats']['comments'], 1)
        self.assertTrue(p.stdout.endswith('\n'))

    def test_saved_input(self):
        self.write('a.py', 'x\n')
        value = self.run_tool('-o', 'json', 'a.py').stdout
        (self.root / 'empty').mkdir()
        p = self.run_tool('-i', 'stdin', '-o', 'json', 'empty', stdin=value)
        self.assertEqual(json.loads(p.stdout)['Total']['code'], 0)
        p = self.run_tool('-i', 'stdin', 'empty', stdin='{}')
        self.assertEqual(p.returncode, 1)

    def test_errors(self):
        p = self.run_tool('--sort', 'not-a-column')
        self.assertEqual(p.returncode, 2)
        self.assertIn('[possible values: files, lines, blanks, code, comments]', p.stderr)
        p = self.run_tool('missing')
        self.assertEqual(p.stderr, "Error: 'missing' not found.\n")
        self.assertEqual(p.returncode, 1)


if __name__ == '__main__':
    unittest.main()
