class LexerTests(unittest.TestCase):
    def assert_counts(self, lang, source, blanks, code, comments, config=None):
        result = parse(lang, source, config)
        self.assertEqual((result['blanks'], result['code'], result['comments']), (blanks, code, comments))
        return result

    def test_comments_and_blank_lines(self):
        self.assert_counts('C', '// heading\n\nx(); // inline\n/* a\n\n*/ y;\n', 1, 1, 4)
        self.assert_counts('Python', '# heading\n\nx=1 # inline\n', 1, 1, 1)
        self.assert_counts('Plain Text', 'hello\n\nworld\n', 1, 0, 2)
        self.assert_counts('JSON', '// not a JSON comment\n\n', 1, 1, 0)

    def test_nested_comments(self):
        self.assert_counts('Rust', '/*a\n/*b\n*/\nx\n*/\n', 0, 0, 5)
        self.assert_counts('C', '/*a\n/*b\n*/\nx\n*/\n', 0, 2, 3)
        self.assert_counts('Haskell', '{-a\n{-b-}\n-}\nx\n', 0, 1, 3)

    def test_strings(self):
        self.assert_counts('Python', 'x="""doc\n\ntext\n"""\n', 0, 4, 0)
        self.assert_counts('Python', 'x="""doc\n\ntext\n"""\n', 0, 0, 4, {'treat_doc_strings_as_comments': True})
        self.assert_counts('Rust', 'let x=r#"a " b\n// text\n\n"#;\n', 0, 4, 0)
        self.assert_counts('C', 'foo=\'"\';\n// text\n', 0, 2, 0)
        self.assert_counts('C', '"a\n// text"\n', 0, 1, 1)

    def test_markdown_and_rust_documentation(self):
        s = self.assert_counts('Markdown', '# Title\n\n```python\n\n#hi\nx\n\n```\n', 1, 0, 3)
        self.assertEqual(s['blobs']['Python'], {'blanks': 0, 'code': 1, 'comments': 1, 'blobs': {}})
        s = self.assert_counts('Rust', '/// text\n/// ```rust\n/// fn x(){}\n/// ```\n\nfn main(){}\n', 1, 1, 0)
        self.assertEqual(s['blobs']['Markdown']['comments'], 3)
        self.assertEqual(s['blobs']['Markdown']['blobs']['Rust']['code'], 1)
        self.assert_counts('MDX', '```python\nx\n```\n', 0, 0, 3)

