        self.assertEqual(s['blobs']['JavaScript'], {'blanks': 1, 'code': 1, 'comments': 1, 'blobs': {}})
        s = self.assert_counts('HTML', '<script>// inline</script>\n', 0, 2, 0)
        self.assertEqual(s['blobs']['JavaScript']['code'], 1)
        self.assert_counts('HTML', '<script>\n\n</script>\n', 1, 2, 0)

