class CLITests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)

    def tearDown(self):
        self.temp.cleanup()

    def run_tool(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(ROOT / 'src'), *args], cwd=self.root,
                              input=stdin, text=True, capture_output=True)

    def write(self, name, source):
        p = self.root / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(source)

    def test_empty_output(self):
        p = self.run_tool('-o', 'json')
        self.assertEqual(p.returncode, 0)
        self.assertEqual(p.stdout, '{"Total":{"blanks":0,"code":0,"comments":0,"reports":[],"children":{},"inaccurate":false}}')
        p = self.run_tool()
        self.assertTrue(p.stdout.endswith('━' * 81 + '\n'))
        self.assertIn(' Total                     0', p.stdout)

    def test_discovery_ignores(self):
        self.write('a.py', '# hi\nx\n')
        self.write('.hidden.py', 'x\n')
        self.write('sub/skip.py', 'x\n')
        self.write('.ignore', 'sub/\n')
        value = json.loads(self.run_tool('-o', 'json').stdout)
        self.assertEqual(len(value['Python']['reports']), 1)
        value = json.loads(self.run_tool('--no-ignore', '--hidden', '-o', 'json').stdout)
        self.assertEqual(len(value['Python']['reports']), 3)
        value = json.loads(self.run_tool('-o', 'json', 'sub').stdout)
        self.assertEqual(value['Python']['reports'][0]['name'], 'sub/skip.py')

    def test_gitignore_requires_repository(self):
        self.write('a.py', 'x\n')
        self.write('.gitignore', '*.py\n')
        self.assertIn('Python', json.loads(self.run_tool('-o', 'json').stdout))
        (self.root / '.git').mkdir()
        self.assertNotIn('Python', json.loads(self.run_tool('-o', 'json').stdout))

    def test_files_types_and_columns(self):
        self.write('a.py', 'x\n')
        self.write('a.rs', '// comment\nx\n')
        p = self.run_tool('-f', '-c', '100', '-t', 'Python')
        self.assertEqual(len(p.stdout.splitlines()[0]), 100)
        self.assertIn('./a.py', p.stdout)
        self.assertNotIn('Rust', p.stdout)

    def test_streaming(self):
        self.write('a.py', '# hi\nx\n')
        p = self.run_tool('--streaming', 'json', 'a.py')
        self.assertEqual(json.loads(p.stdout)['stats']['stats']['comments'], 1)
        self.assertTrue(p.stdout.endswith('\n'))

    def test_saved_input(self):
        self.write('a.py', 'x\n')
        value = self.run_tool('-o', 'json', 'a.py').stdout
        (self.root / 'empty').mkdir()
        p = self.run_tool('-i', 'stdin', '-o', 'json', 'empty', stdin=value)
        self.assertEqual(json.loads(p.stdout)['Total']['code'], 0)
        p = self.run_tool('-i', 'stdin', 'empty', stdin='{}')
        self.assertEqual(p.returncode, 1)

    def test_errors(self):
        p = self.run_tool('--sort', 'not-a-column')
        self.assertEqual(p.returncode, 2)
        self.assertIn('[possible values: files, lines, blanks, code, comments]', p.stderr)
        p = self.run_tool('missing')
        self.assertEqual(p.stderr, "Error: 'missing' not found.\n")
        self.assertEqual(p.returncode, 1)


if __name__ == '__main__':
    unittest.main()
